You are implementing Task 4.2: Add trend chart rendering JavaScript

## Task Description

**Files:**
- Modify: `BCCAFinance.html` (in the script section)

**Step 1: Add trends data variable and fetch function (after other data variables)**

Find where data variables are declared and add:

```javascript
    // Trends data
    let trendsData = null;
    let selectedRange = "30";

    async function loadTrendsData() {
      try {
        const response = await fetch(getBlobUrl('trends.json'));
        if (!response.ok) {
          throw new Error('Failed to load trends.json: ' + response.status);
        }
        trendsData = await response.json();
        return true;
      } catch (error) {
        console.error('Error loading trends data:', error);
        return false;
      }
    }
```

**Step 2: Add chart rendering functions**

```javascript
    function showChartEmptyState(chartId, show) {
      const chart = document.getElementById(chartId);
      const empty = document.getElementById(chartId + '-empty');
      if (chart) chart.style.display = show ? 'none' : 'block';
      if (empty) empty.style.display = show ? 'flex' : 'none';
    }

    function renderCashChart() {
      if (!trendsData) return;

      const daily = trendsData.cash?.daily || [];
      const monthly = trendsData.cash?.monthly || [];

      // Combine and filter by selected range
      let data = filterByRange([...daily, ...monthly.map(function(m) {
        return {
          date: m.month + "-15",  // Approximate mid-month
          bank: m.bank,
          investments: m.investments,
          total: m.total
        };
      })]);

      if (data.length === 0) {
        showChartEmptyState('chart-cash', true);
        return;
      }

      showChartEmptyState('chart-cash', false);

      var traces = [
        {
          x: data.map(function(d) { return d.date || d.month; }),
          y: data.map(function(d) { return d.total; }),
          name: 'Total',
          type: 'scatter',
          mode: 'lines',
          line: { color: '#2563eb', width: 3 }
        },
        {
          x: data.map(function(d) { return d.date || d.month; }),
          y: data.map(function(d) { return d.bank; }),
          name: 'Bank',
          type: 'scatter',
          mode: 'lines',
          line: { color: '#16a34a', width: 2, dash: 'dash' }
        },
        {
          x: data.map(function(d) { return d.date || d.month; }),
          y: data.map(function(d) { return d.investments; }),
          name: 'Investments',
          type: 'scatter',
          mode: 'lines',
          line: { color: '#9333ea', width: 2, dash: 'dash' }
        }
      ];

      var layout = {
        margin: { t: 20, r: 20, b: 40, l: 60 },
        xaxis: { title: '' },
        yaxis: { title: '', tickformat: '$,.0f' },
        legend: { orientation: 'h', y: -0.15 },
        hovermode: 'x unified'
      };

      Plotly.newPlot('chart-cash', traces, layout, { responsive: true });
    }

    function renderBudgetChart() {
      if (!trendsData) return;

      var weekly = trendsData.budget?.weekly || [];
      var data = filterByRange(weekly.map(function(w) {
        return { date: w.week, week: w.week, committees: w.committees };
      }));

      if (data.length === 0) {
        showChartEmptyState('chart-budget', true);
        return;
      }

      showChartEmptyState('chart-budget', false);

      var committees = ['utilities', 'maintenance', 'finance', 'board', 'commonHouse', 'landscape', 'meals'];
      var colors = ['#2563eb', '#16a34a', '#dc2626', '#9333ea', '#f59e0b', '#06b6d4', '#ec4899'];
      var names = ['Utilities', 'Maintenance', 'Finance', 'Board', 'Common House', 'Landscape', 'Meals'];

      var traces = committees.map(function(key, i) {
        return {
          x: data.map(function(d) { return d.week; }),
          y: data.map(function(d) { return d.committees?.[key] || 0; }),
          name: names[i],
          type: 'scatter',
          mode: 'lines',
          stackgroup: 'one',
          line: { color: colors[i] }
        };
      });

      var layout = {
        margin: { t: 20, r: 20, b: 40, l: 60 },
        xaxis: { title: '' },
        yaxis: { title: '', tickformat: '$,.0f' },
        legend: { orientation: 'h', y: -0.15 },
        hovermode: 'x unified'
      };

      Plotly.newPlot('chart-budget', traces, layout, { responsive: true });
    }

    function renderYoYChart() {
      if (!trendsData || !trendsData.yoy) {
        showChartEmptyState('chart-yoy', true);
        var subtitle = document.getElementById('yoy-subtitle');
        if (subtitle) {
          subtitle.textContent = 'Will be available once prior year data is loaded';
        }
        return;
      }

      showChartEmptyState('chart-yoy', false);

      var yoy = trendsData.yoy;
      var monthly = yoy.monthly || [];
      var monthNames = ['', 'Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

      var subtitle = document.getElementById('yoy-subtitle');
      if (subtitle) {
        subtitle.textContent = yoy.current_year + ' vs ' + yoy.prior_year + ' monthly spending';
      }

      var traces = [
        {
          x: monthly.map(function(m) { return monthNames[m.month]; }),
          y: monthly.map(function(m) { return m.current?.total || 0; }),
          name: String(yoy.current_year),
          type: 'bar',
          marker: { color: '#2563eb' }
        },
        {
          x: monthly.map(function(m) { return monthNames[m.month]; }),
          y: monthly.map(function(m) { return m.prior?.total || 0; }),
          name: String(yoy.prior_year),
          type: 'bar',
          marker: { color: '#94a3b8' }
        }
      ];

      var layout = {
        margin: { t: 20, r: 20, b: 40, l: 60 },
        barmode: 'group',
        xaxis: { title: '' },
        yaxis: { title: '', tickformat: '$,.0f' },
        legend: { orientation: 'h', y: -0.15 },
        hovermode: 'x unified'
      };

      Plotly.newPlot('chart-yoy', traces, layout, { responsive: true });
    }

    function filterByRange(data) {
      if (!data || data.length === 0) return [];

      var now = new Date();
      var cutoff;

      switch (selectedRange) {
        case "30":
          cutoff = new Date(now - 30 * 24 * 60 * 60 * 1000);
          break;
        case "90":
          cutoff = new Date(now - 90 * 24 * 60 * 60 * 1000);
          break;
        case "ytd":
          cutoff = new Date(now.getFullYear(), 0, 1);
          break;
        case "all":
        default:
          return data.slice().sort(function(a, b) {
            var aKey = a.date || a.month || a.week;
            var bKey = b.date || b.month || b.week;
            return aKey.localeCompare(bKey);
          });
      }

      var cutoffStr = cutoff.toISOString().slice(0, 10);
      return data
        .filter(function(d) {
          var key = d.date || d.month || d.week;
          return key >= cutoffStr;
        })
        .sort(function(a, b) {
          var aKey = a.date || a.month || a.week;
          var bKey = b.date || b.month || b.week;
          return aKey.localeCompare(bKey);
        });
    }

    function renderAllTrendCharts() {
      renderCashChart();
      renderBudgetChart();
      renderYoYChart();
    }
```

**Step 3: Add range selector event handler and init function**

```javascript
    function initTrendRangeSelector() {
      var buttons = document.querySelectorAll('.trend-range-btn');
      buttons.forEach(function(btn) {
        btn.addEventListener('click', function() {
          buttons.forEach(function(b) { b.classList.remove('active'); });
          btn.classList.add('active');
          selectedRange = btn.dataset.range;
          renderAllTrendCharts();
        });
      });
    }

    async function initTrends() {
      var loading = document.getElementById('trends-loading');
      var error = document.getElementById('trends-error');

      // Show loading
      loading.style.display = 'flex';
      document.getElementById('chart-cash').style.display = 'none';
      document.getElementById('chart-budget').style.display = 'none';
      document.getElementById('chart-yoy').style.display = 'none';

      var success = await loadTrendsData();

      loading.style.display = 'none';

      if (!success) {
        error.style.display = 'flex';
        return;
      }

      // Show charts
      document.getElementById('chart-cash').style.display = 'block';
      document.getElementById('chart-budget').style.display = 'block';
      document.getElementById('chart-yoy').style.display = 'block';

      initTrendRangeSelector();
      renderAllTrendCharts();
    }
```

**Step 4: Call initTrends from initDashboard**

Find the `initDashboard` function and after `renderCommitteeTable();` add:

```javascript
      // Initialize trends
      await initTrends();
```

